fn resolve_ocr_api_key_for_run(
    ordinary_chat_acceptance_enabled: bool,
    load_normal_credential: impl FnOnce() -> Result<Vec<u8>, String>,
) -> Result<Vec<u8>, String> {
    if ordinary_chat_acceptance_enabled {
        Ok(Vec::new())
    } else {
        load_normal_credential()
    }
}

