    #[test]
    fn v2_picker_bridge_reads_only_the_selected_package_and_returns_a_content_free_receipt() {
        let directory = tempdir().unwrap();
        let store = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let mut exchange: Value = serde_json::from_str(include_str!(
            "../../../protocol/fixtures/nfai.exchange.v2.golden.json"
        ))
        .unwrap();
        let asset_hash = sha256(b"a");
        for attachment in exchange["knowledge"][0]["attachments"]
            .as_array_mut()
            .unwrap()
        {
            attachment["entry"] = Value::String(format!("assets/{asset_hash}"));
            attachment["sha256"] = Value::String(asset_hash.clone());
        }
        exchange["export"]["semanticHash"] = Value::String(semantic_hash(&exchange).unwrap());
        let selected = directory.path().join("selected.nfai-exchange");
        fs::write(
            &selected,
            p6_workspace_exchange_v2::package(
                &exchange,
                &BTreeMap::from([(format!("assets/{asset_hash}"), b"a".to_vec())]),
            )
            .unwrap(),
        )
        .unwrap();

        let receipt = store
            .import_selected_v2_workspace_exchange(selected.to_str().unwrap())
            .unwrap();
        assert!(!receipt.replayed);
        assert_eq!(receipt.asset_count, 1);
        assert_eq!(receipt.root_counts.get("knowledge"), Some(&1));
        let serialized = serde_json::to_string(&receipt).unwrap();
        assert!(!serialized.contains(selected.to_str().unwrap()));
        assert!(!serialized.contains("displayName"));

        let replay = store
            .import_selected_v2_workspace_exchange(selected.to_str().unwrap())
            .unwrap();
        assert!(replay.replayed);
        let documents_ui_selected = directory.path().join("selected.nfai-exchange.zip");
        fs::copy(&selected, &documents_ui_selected).unwrap();
        let documents_ui_replay = store
            .import_selected_v2_workspace_exchange(documents_ui_selected.to_str().unwrap())
            .unwrap();
        assert!(documents_ui_replay.replayed);
        let generic_android_zip = directory.path().join("android-v2-owner-acceptance.zip");
        fs::copy(&selected, &generic_android_zip).unwrap();
        let generic_android_replay = store
            .import_selected_v2_workspace_exchange(generic_android_zip.to_str().unwrap())
            .unwrap();
        assert!(generic_android_replay.replayed);
        let connection = store.connection().unwrap();
        let v1_rows: i64 = connection
            .query_row(
                "SELECT (SELECT COUNT(*) FROM workspaces)+(SELECT COUNT(*) FROM workspace_exchange)+(SELECT COUNT(*) FROM import_journal)",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(v1_rows, 0);
        let rejected = store
            .import_selected_v2_workspace_exchange(
                directory.path().join("not-selected.txt").to_str().unwrap(),
            )
            .unwrap_err();
        assert!(rejected.contains("文件类型无效"));
        assert!(!rejected.contains("not-selected.txt"));
        for invalid_name in [
            "selected.nfai-exchange.zip.exe",
            "selected.zip.zip",
            "selected.zip.nfai-exchange",
            "selected.nfai-exchange.nfai-exchange",
        ] {
            let invalid = directory.path().join(invalid_name);
            fs::copy(&selected, &invalid).unwrap();
            let rejected = store
                .import_selected_v2_workspace_exchange(invalid.to_str().unwrap())
                .unwrap_err();
            assert!(rejected.contains("文件类型无效"));
            assert!(!rejected.contains(invalid_name));
        }
    }

    #[test]
    fn v2_settings_reexport_reads_only_committed_private_owner_and_returns_content_free_readback() {
        let directory = tempdir().unwrap();
        let store = DesktopWorkspaceStore::open(directory.path().join("app-data")).unwrap();
        let mut exchange: Value = serde_json::from_str(include_str!(
            "../../../protocol/fixtures/nfai.exchange.v2.golden.json"
        ))
        .unwrap();
        let asset_hash = sha256(b"a");
        for attachment in exchange["knowledge"][0]["attachments"]
            .as_array_mut()
            .unwrap()
        {
            attachment["entry"] = Value::String(format!("assets/{asset_hash}"));
            attachment["sha256"] = Value::String(asset_hash.clone());
        }
        exchange["export"]["semanticHash"] = Value::String(semantic_hash(&exchange).unwrap());
        let selected = directory.path().join("selected.nfai-exchange");
        fs::write(
            &selected,
            p6_workspace_exchange_v2::package(
                &exchange,
                &BTreeMap::from([(format!("assets/{asset_hash}"), b"a".to_vec())]),
            )
            .unwrap(),
        )
        .unwrap();
        let imported = store
            .import_selected_v2_workspace_exchange(selected.to_str().unwrap())
            .unwrap();
        let committed = store.list_committed_v2_workspace_exchanges().unwrap();
        assert_eq!(committed.len(), 1);
        assert_eq!(committed[0].workspace_id, imported.workspace_id);
        assert_eq!(committed[0].asset_count, 1);

        let target = directory.path().join("reexported.nfai-exchange");
        let receipt = store
            .reexport_selected_v2_workspace_exchange(
                &committed[0].workspace_id,
                target.to_str().unwrap(),
            )
            .unwrap();
        assert_eq!(receipt.semantic_hash, imported.semantic_hash);
        assert_eq!(receipt.root_counts, committed[0].root_counts);
        assert_eq!(receipt.asset_count, committed[0].asset_count);
        let readback = p6_workspace_exchange_v2::preflight(fs::read(&target).unwrap()).unwrap();
        assert_eq!(readback.receipt.semantic_hash, receipt.semantic_hash);
        assert_eq!(readback.receipt.root_counts, receipt.root_counts);

        let serialized = serde_json::to_string(&receipt).unwrap();
        assert!(!serialized.contains(target.to_str().unwrap()));
        assert!(!serialized.contains("displayName"));
        assert!(store
            .reexport_selected_v2_workspace_exchange(
                &committed[0].workspace_id,
                directory.path().join("wrong.zip").to_str().unwrap()
            )
            .unwrap_err()
            .contains("输出文件类型无效"));
        assert!(store
            .reexport_selected_v2_workspace_exchange(
                "workspace-v2-not-committed",
                target.to_str().unwrap()
            )
            .unwrap_err()
            .contains("记录不存在"));
        let connection = store.connection().unwrap();
        let v1_rows: i64 = connection
            .query_row(
                "SELECT (SELECT COUNT(*) FROM workspaces)+(SELECT COUNT(*) FROM workspace_exchange)+(SELECT COUNT(*) FROM import_journal)",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(v1_rows, 0);
    }

